// Checks for the homepage Quick Scent Match (js/quiz.js) — the adapter over
// js/recs.js. Plain assert, no framework; runs inside `npm run build` so a
// regression fails the deploy. Part 1 uses a synthetic catalogue (edge cases);
// part 2 the real data/recs.json when present (it is generated by the build).
const assert = require('assert');
const fs = require('fs');
const path = require('path');
const R = require('../js/recs.js');
const Q = require('../js/quiz.js');

// ── 1. synthetic catalogue (recs.json format) ────────────────────
const vocab = {
  b: ['Alpha House', 'Beta House', 'Gamma House', 'Delta House'],
  f: ['Woody', 'Citrus', 'Fresh', 'Gourmand', 'Vanilla', 'Aquatic', 'Floral'],
  a: ['Woody', 'Citrus', 'Fresh', 'Sweet', 'Vanilla', 'Amber', 'Aquatic', 'Marine', 'Floral', 'Oud', 'Powdery', 'Musky.'],
  n: [],
  o: ['Everyday', 'Office', 'Formal', 'Date Night', 'Evening', 'Summer', 'Winter'],
  k: ['EDP', 'Extrait', 'EDT'],
};
let idx = 0;
const item = (id, o) => Object.assign({ id, nm: id.toUpperCase(), b: 0, c: 'r', f: [], a: [], n: [], o: [], g: 1, k: -1,
  s: [[3, 200], [5, 320]], sp: 0, p: 200, i: 1, bs: 0, t: [], v: 1 }, o, { _i: idx++ });
const items = [
  item('w1', { b: 0, f: [0], a: [0, 5], o: [1, 2], k: 1, s: [[3, 150]], p: 150, bs: 1 }),     // woody, office, extrait
  item('w2', { b: 0, f: [0], a: [0, 9], o: [3, 4], s: [[3, 180]], p: 180 }),                  // woody + oud, dates
  item('w3', { b: 3, f: [0], a: [0], o: [], s: [[3, 220]], p: 220, g: 3 }),                   // woody, NO occasions, unisex (own house)
  item('w4', { b: 1, f: [0], a: [0], o: [0], s: [[3, 260]], p: 260 }),                        // woody, everyday
  item('c1', { b: 1, f: [1, 2], a: [1, 2], o: [0, 5], k: 2, s: [[3, 170]], p: 170, g: 3 }),   // citrus/fresh, unisex EDT
  item('c2', { b: 2, f: [1], a: [1], o: [1], s: [[3, 300]], p: 300 }),
  item('s1', { b: 2, f: [3, 4], a: [3, 4, 5], o: [6], s: [[3, 400]], p: 400, g: 3 }),          // sweet, winter, unisex
  item('aq', { b: 3, f: [5], a: [6, 7], o: [5], s: [[3, 230]], p: 230 }),                      // aquatic
  item('fl', { b: 3, f: [6], a: [8, 10, 11], o: [0], s: [[3, 240]], p: 240, g: 3 }),           // floral, unisex
  item('oos', { b: 1, f: [0], a: [0], o: [1], i: 0, p: 150 }),                                 // out of stock
  item('ex', { b: 2, f: [0], a: [0], o: [1], c: 'e', p: 150 }),                                // exclusive collection
  item('no3', { b: 2, f: [0], a: [0], o: [1], s: [[5, 300]], p: 300 }),                        // no 3 ml size
];
const model = R.prepareData({ v: 1, vocab, items });
assert.ok(model, 'synthetic model builds');
const ans = o => Object.assign({ who: 'him', tiles: [], occ: [], strength: 'any', budget: null }, o);
const ids = res => res.picks.map(p => p.id);

// Budget bands — tie-safe, exact, edge cases
{
  assert.deepStrictEqual(Q.bands([200, 200, 200, 200]), [{ min: 200, max: 200 }], 'identical prices → one band');
  assert.deepStrictEqual(Q.bands([150, 150, 300]), [{ min: 150, max: 150 }, { min: 300, max: 300 }], '2 distinct → one band each');
  assert.strictEqual(Q.bands([150, 160, 170, 400, 500]).length, 1, 'tiny catalogue collapses to one band');
  assert.deepStrictEqual(Q.bands([]), [], 'no prices → no bands');
  const tied = [150, 150, 150, 150, 150, 150, 150, 150, 190, 190, 190, 190, 190, 190, 190, 190, 190, 190, 190, 220, 230, 240, 250, 260, 300, 320, 350, 400, 450, 500];
  const b = Q.bands(tied);
  tied.forEach(p => assert.strictEqual(b.filter(x => p >= x.min && p <= x.max).length, 1, 'every price in exactly one band: ' + p));
  b.slice(1).forEach((x, i) => assert.ok(x.min > b[i].max, 'bands never overlap / split a price'));
}

// Filters: stock, collection, 3 ml, gender, budget
{
  const all = Q.excluded(model, ans({}), []);
  ['oos', 'ex', 'no3'].forEach(id => assert.ok(all.includes(id), id + ' excluded'));
  const her = Q.excluded(model, ans({ who: 'her' }), []);
  model.items.filter(it => !her.includes(it.id)).forEach(it => assert.strictEqual(it.g, 3, 'Her → unisex only'));
  const anyone = Q.excluded(model, ans({ who: 'anyone' }), []);
  assert.ok(!anyone.includes('w1') && !anyone.includes('c1'), 'Anyone → men + unisex (no gender filter)');
  const bandList = [{ key: 'b0', min: 150, max: 180 }];
  const cheap = Q.excluded(model, ans({ budget: 'b0' }), bandList);
  model.items.filter(it => !cheap.includes(it.id)).forEach(it => assert.ok(Q.price3(it) >= 150 && Q.price3(it) <= 180, 'budget uses the 3 ml effective price'));
}

// Anchor vector: recs' key space, L2-normalised
{
  const v = Q.buildAnchor(model, ['woody', 'fresh']);
  assert.ok(v.size > 0);
  v.forEach((w, k) => assert.ok(/^[fa]\d+$/.test(k), 'anchor keys are f<idx>/a<idx>: ' + k));
  let n = 0; v.forEach(w => { n += w * w; });
  assert.ok(Math.abs(Math.sqrt(n) - 1) < 1e-9, 'anchor is L2-normalised');
  assert.strictEqual(Q.buildAnchor(model, ['nope']).size, 0, 'unknown cards add nothing');
}

// Unknown vs mismatch: never penalise missing metadata, renormalise weights
{
  const it = id => model.items.find(x => x.id === id);
  assert.strictEqual(Q.occasionFit(it('w3'), ans({ occ: ['office'] }), model), null, 'no occasions on the item → unknown');
  assert.strictEqual(Q.occasionFit(it('w2'), ans({ occ: ['office'] }), model), 0, 'listed occasions, none chosen → mismatch');
  assert.strictEqual(Q.occasionFit(it('w1'), ans({ occ: ['office'] }), model), 1);
  assert.strictEqual(Q.occasionFit(it('w1'), ans({ occ: [] }), model), null, 'not asked → no signal');
  const flo = it('fl');                                   // accords Floral/Powdery/Musky: none light/rich, k unknown
  assert.strictEqual(Q.intensity(flo, model), null, 'no classified accord + no concentration → unknown intensity');
  assert.strictEqual(Q.strengthFit(flo, ans({ strength: 'strong' }), model), null);
  assert.ok(Q.intensity(it('w1'), model) > Q.intensity(it('c1'), model), 'rich + extrait reads stronger than fresh EDT');
  // Same taste: unknown occasion must not lose to a genuine mismatch, and must equal its taste score
  const pool = [{ id: 'w3', item: it('w3'), cos: 0.5 }, { id: 'w2', item: it('w2'), cos: 0.5 }];
  const r = Q.rerank(pool, ans({ occ: ['office'] }), model);
  const u = r.find(x => x.id === 'w3'), m = r.find(x => x.id === 'w2');
  assert.ok(u.score > m.score, 'unknown (renormalised) ranks above a mismatch');
  assert.ok(Math.abs(u.score - u.taste) < 1e-9, 'unknown occasion drops out of the weights');
}

// Matching on the synthetic catalogue
{
  const a1 = Q.match(model, ans({ tiles: ['woody'], occ: ['office'] }), R.rank);
  const a2 = Q.match(model, ans({ tiles: ['woody'], occ: ['office'] }), R.rank);
  assert.deepStrictEqual(ids(a1), ids(a2), 'deterministic');
  assert.ok(a1.picks.length <= 3 && new Set(ids(a1)).size === a1.picks.length, '≤ 3 unique');
  assert.strictEqual(a1.picks[0].label, 'Best Match');
  const per = {}; a1.picks.forEach(p => { per[p.item.b] = (per[p.item.b] || 0) + 1; });
  Object.values(per).forEach(c => assert.ok(c <= 2, 'brand cap 2'));
  ['oos', 'ex', 'no3'].forEach(id => assert.ok(!ids(a1).includes(id), id + ' never shown'));
  // Occasion: a verified match beats a genuine mismatch; the item with NO
  // occasion data (w3) is scored on taste alone — never placed below a mismatch.
  const pos = (res, id) => ids(res).indexOf(id);
  assert.ok(pos(a1, 'w1') >= 0 && (pos(a1, 'w2') < 0 || pos(a1, 'w1') < pos(a1, 'w2')), 'office: office-listed w1 above dates-only w2');
  assert.ok(pos(a1, 'w3') >= 0 && (pos(a1, 'w2') < 0 || pos(a1, 'w3') < pos(a1, 'w2')), 'unknown occasion not below a mismatch');
  const dates = Q.match(model, ans({ tiles: ['woody'], occ: ['dates'] }), R.rank);
  assert.ok(pos(dates, 'w2') >= 0 && (pos(dates, 'w1') < 0 || pos(dates, 'w2') < pos(dates, 'w1')), 'dates: w2 above office-only w1 — occasion changes the order');
  // Scent similarity ignores metadata richness: w1 and w3 share the same woody
  // core; w1's extra occasions / concentration must not make it "less woody".
  const vw = Q.buildAnchor(model, ['woody']);
  const sims = Q.rerank([{ id: 'w1', item: model.items.find(x => x.id === 'w1'), cos: 0.1 }, { id: 'w4', item: model.items.find(x => x.id === 'w4'), cos: 0.9 }], ans({}), model, vw);
  assert.ok(Math.abs(sims.find(r => r.id === 'w4').taste - 1) < 1e-9, 'taste uses family/accord dims, not recs cosine');
  // Strength moves scores the right way (taste still leads: 15 % weight). The
  // real-catalogue section asserts it changes the top 3.
  const woodyPool = R.rank(model, [], { anchor: { vec: vw }, exclude: Q.excluded(model, ans({}), []), collection: 'r', limit: 24, pool: 24, brandCap: 6, minCos: Q.MIN_COS, shuffle: false });
  const scoreOf = (s, id) => Q.rerank(woodyPool, ans({ strength: s }), model, vw).find(r => r.id === id).score;
  assert.ok(scoreOf('strong', 'w1') > scoreOf('subtle', 'w1'), 'rich extrait scores higher for Strong than Subtle');
  assert.strictEqual(scoreOf('strong', 'w3'), scoreOf('subtle', 'w3'), 'unknown intensity: unaffected by the strength answer');
  // Explore with other cards: slot from outside the chosen families and defining accords
  const ex = Q.match(model, ans({ tiles: ['woody', Q.EXPLORE] }), R.rank);
  const explorePick = ex.picks.find(p => p.explore);
  assert.ok(explorePick, 'explore slot filled');
  assert.ok(!(explorePick.item.f || []).includes(0) && !(explorePick.item.a || []).slice(0, 5).includes(0), 'explore is outside the chosen scent');
  assert.strictEqual(explorePick.label, 'Worth Exploring');
  ex.picks.filter(p => !p.explore).forEach(p => assert.notStrictEqual(p.label, 'Worth Exploring', 'Worth Exploring is the explore pick only'));
  // Explore alone: distinct families
  const ea = Q.match(model, ans({ tiles: [Q.EXPLORE] }), R.rank);
  const fams = ea.picks.map(p => p.item.f[0]);
  assert.strictEqual(new Set(fams).size, fams.length, 'explore alone → different families');
  // Nothing fits → none; taste floor → fewer, never padded
  const none = Q.match(model, ans({ who: 'her', tiles: ['woody'], budget: 'b9' }), R.rank, { bands: [{ key: 'b9', min: 1, max: 2 }] });
  assert.strictEqual(none.status, 'none');
  assert.deepStrictEqual(none.picks, []);
  const sweetHer = Q.match(model, ans({ who: 'her', tiles: ['sweet'] }), R.rank);
  sweetHer.picks.filter(p => !p.explore).forEach(p => assert.ok(p.taste >= Q.MIN_TASTE, 'every pick clears the taste floor'));
  // Why lines only from the item's own attributes
  const w3why = Q.whyLine(model.items.find(x => x.id === 'w3'), ans({ tiles: ['woody'], occ: ['office'] }), model, {});
  assert.ok(!/good for/.test(w3why), 'no occasion claim when the item lists none');
  assert.ok(/Woody/.test(w3why));
  const w1why = Q.whyLine(model.items.find(x => x.id === 'w1'), ans({ tiles: ['woody'], strength: 'strong' }), model, {});
  assert.ok(/Extrait de Parfum/.test(w1why), 'known concentration named in full');
  const w1subtle = Q.whyLine(model.items.find(x => x.id === 'w1'), ans({ tiles: ['woody'], strength: 'subtle' }), model, {});
  assert.ok(!/Extrait/.test(w1subtle), 'a concentration that contradicts the answer is not named');
  const w4office = Q.whyLine(model.items.find(x => x.id === 'w4'), ans({ tiles: ['woody'], occ: ['office'] }), model, {});
  assert.ok(/better for everyday wear/.test(w4office), 'asked occasion not listed → says what it is for instead');
  assert.ok(!Q.TILES.aquatic.a2.includes('Ozonic'), 'Ozonic is fresh air, not water');
  const w4why = Q.whyLine(model.items.find(x => x.id === 'w4'), ans({ tiles: ['woody'], strength: 'strong' }), model, {});
  assert.ok(!/Parfum|Toilette/.test(w4why), 'unknown concentration never named');
  assert.strictEqual(Q.cautionFor(model.items.find(x => x.id === 'w2'), ['fresh'], model), 'Heads-up: it has an oud edge.');
  assert.strictEqual(Q.cautionFor(model.items.find(x => x.id === 'w2'), ['woody'], model), '', 'no heads-up when oud was asked for');
}

// "Try all 3": live-verified only, no stale fallback, exact cart delta
{
  const picks = ['w1', 'c1', 's1'].map(id => ({ id, item: model.items.find(x => x.id === id) }));
  assert.deepStrictEqual(Q.bundleLines(picks, null).ok, false, 'no live data → bundle not allowed');
  const live = new Map([
    ['w1', { inStock: true, sizes: [{ ml: 3, price: 150 }, { ml: 5, price: 240 }], salePercent: 0, name: 'W1', brand: 'Alpha House' }],
    ['c1', { inStock: true, sizes: [{ ml: 3, price: 200 }], salePercent: 10, name: 'C1', brand: 'Beta House' }],
    ['s1', { inStock: false, sizes: [{ ml: 3, price: 400 }], salePercent: 0, name: 'S1', brand: 'Gamma House' }],
  ]);
  const b = Q.bundleLines(picks, live);
  assert.deepStrictEqual(b.dropped, ['s1'], 'out-of-stock pick dropped');
  assert.deepStrictEqual(b.lines.map(l => [l.id, l.ml, l.price]), [['w1', 3, 150], ['c1', 3, 180]], 'live 3 ml effective prices');
  assert.strictEqual(b.total, 330);
  const noThree = Q.bundleLines([picks[0]], new Map([['w1', { inStock: true, sizes: [{ ml: 5, price: 240 }], salePercent: 0 }]]));
  assert.strictEqual(noThree.lines.length, 0, 'no 3 ml size → not bundled');
  const before = [{ key: 'w1_3', qty: 1 }];
  assert.ok(Q.cartAdded(before, [{ key: 'w1_3', qty: 2 }, { key: 'c1_3', qty: 1 }], b.lines).ok, 'each line +1');
  assert.deepStrictEqual(Q.cartAdded(before, [{ key: 'w1_3', qty: 3 }, { key: 'c1_3', qty: 1 }], b.lines).failed, ['w1'], 'double add detected');
  assert.deepStrictEqual(Q.cartAdded(before, [{ key: 'w1_3', qty: 2 }], b.lines).failed, ['c1'], 'missing line detected');
}

// Copy: no performance claims, no technology names in shopper-visible strings
{
  const src = fs.readFileSync(path.join(__dirname, '..', 'js', 'quiz.js'), 'utf8').replace(/\/\/[^\n]*|\/\*[\s\S]*?\*\//g, '');
  const strings = (src.match(/'(?:[^'\\\n]|\\.)*'/g) || []).join(' ');
  assert.ok(!/\b(lasts?|long[- ]lasting|longevity|projection|sillage|hours?|AI|Gemini|algorithm|machine learning)\b/i.test(strings), 'no claims or tech words in copy');
  assert.ok(!/%/.test(Object.values(Q.TILES).map(t => t.label).join('')), 'no percentages in labels');
}
console.log('test-quiz: synthetic checks passed');

// ── 2. real catalogue ────────────────────────────────────────────
const real = path.join(__dirname, '..', 'data', 'recs.json');
if (fs.existsSync(real)) {
  const m = R.prepareData(JSON.parse(fs.readFileSync(real, 'utf8')));
  const buy = m.items.filter(it => it.i && it.c === 'r' && Q.price3(it) != null);
  const bands = Q.bandOptions(m);
  assert.ok(bands.length >= 1);
  buy.forEach(it => assert.strictEqual(bands.filter(b => Q.price3(it) >= b.min && Q.price3(it) <= b.max).length, 1, 'real product in exactly one band: ' + it.id));
  bands.slice(1).forEach((b, i) => assert.ok(b.min > bands[i].max, 'real bands never split a price'));

  const top = a => Q.match(m, a, R.rank).picks.map(p => p.id).join();
  // Gender
  const her = Q.match(m, ans({ who: 'her', tiles: ['woody'] }), R.rank);
  her.picks.forEach(p => assert.strictEqual(p.item.g, 3, 'Her → unisex only (real)'));
  // Ranking responds to every relevant preference (not just a valid vector)
  assert.notStrictEqual(top(ans({ tiles: ['fresh'] })), top(ans({ tiles: ['woody'] })), 'scent cards change results');
  assert.notStrictEqual(top(ans({ tiles: ['fresh'], occ: ['office'] })), top(ans({ tiles: ['fresh'], occ: ['dates'] })), 'occasion changes results');
  assert.notStrictEqual(top(ans({ tiles: ['woody'], strength: 'subtle' })), top(ans({ tiles: ['woody'], strength: 'strong' })), 'strength changes results');

  // Integrity + pool validation across answer combinations. Why the constants in
  // js/quiz.js are what they are (real catalogue, 2026-10-29):
  //  - MIN_TASTE 0.35: without a floor 2.7 % of shown picks shared < 0.2 of the
  //    chosen scents (carried only by occasion/strength); now dropped — show
  //    fewer, never pad.
  //  - POOL 24: many products tie near the top on shared accords, so a 12 pool
  //    cut ties before occasion/strength could act (top 3 differed from a full
  //    re-rank in 2.9 % of cases, left-out taste up to 0.91); 24 → 0.5 %.
  //  - POOL_BRAND_CAP 6: a cap of 3 inside the pool crowded out one house's
  //    strong matches before the final cap of 2 applied.
  //  - W 0.55/0.30/0.15 and TASTE decay .05 / cover .15: chosen by blind expert
  //    ranking of three variants on 40 profiles (20 held out). Equal accord weight
  //    let a ninth accord carry a pick (a sweet vanilla scent shown for Aquatic via
  //    Aquatic #9); decay ≥ .1 changed 63-71 % of results and broke known-good
  //    answers. Per-card anchor normalisation added churn without gains (dropped).
  const V = m.vocab, idx = (list, labels) => labels.map(l => list.indexOf(l)).filter(i => i >= 0);
  const flF = idx(V.f, ['Floral']), flA = idx(V.a, ['Floral', 'White Floral', 'Rose', 'Iris', 'Violet']);
  const mkF = idx(V.f, ['Musk']), mkA = idx(V.a, ['Musky']);
  const muskOK = it => (it.f || []).some(i => mkF.includes(i)) || (it.a || []).slice(0, 5).some(i => mkA.includes(i));
  const oudIdx = V.a.indexOf('Oud');
  const floralOK = it => (it.f || []).some(i => flF.includes(i)) || (it.a || []).slice(0, 5).some(i => flA.includes(i));
  // Ties (to rounding) fall through to bestseller first
  for (const t of ['fresh', 'woody', 'spicy', 'sweet']) {
    const a = ans({ tiles: [t] }), vec = Q.buildAnchor(m, [t]);
    const all = Q.rerank(R.rank(m, [], { anchor: { vec }, exclude: Q.excluded(m, a, bands), collection: 'r', limit: 500, pool: 500, brandCap: 99, minCos: 0, shuffle: false }), a, m, vec);
    for (let i = 1; i < all.length; i++) if (Math.abs(all[i - 1].score - all[i].score) <= 1e-9) assert.ok(all[i - 1].item.bs >= all[i].item.bs, 'tie → bestseller first');
  }
  // "Woody & Oud": an oud shows for a woody evening ask; it is not forced into a subtle office one
  const oudIn = r => r.picks.some(p => Q.isOud(p.item, m));
  if (oudIdx >= 0) {
    const bi = m.items.find(x => /Bois Imp/i.test(x.nm));
    if (bi) assert.ok(!Q.isOud(bi, m), 'an oud-like accord without an oud/agarwood note is not oud');
    assert.ok(oudIn(Q.match(m, ans({ tiles: ['woody'], occ: ['dates'], strength: 'strong' }), R.rank, { bands })), 'woody + evening + strong includes an oud');
    const quiet = Q.match(m, ans({ tiles: ['woody'], occ: ['office'], strength: 'subtle' }), R.rank, { bands });
    quiet.picks.filter(p => Q.isOud(p.item, m)).forEach(p => assert.ok(p.occasionFit !== 0, 'no off-occasion oud forced into a subtle office ask'));
  }
  // Explore alone: three directions, at most one light pick
  for (const w of ['him', 'her', 'anyone']) {
    const eaR = Q.match(m, ans({ who: w, tiles: [Q.EXPLORE] }), R.rank, { bands });
    assert.ok(eaR.picks.filter(p => { const I = Q.intensity(p.item, m); return I != null && I < 0.35; }).length <= 1, 'explore alone: at most one light pick');
  }
  const tiles = Object.keys(Q.TILES), occs = [[], ['office'], ['dates'], ['everyday'], ['parties']];
  const strengths = ['any', 'subtle', 'balanced', 'strong'], whos = ['him', 'her', 'anyone'], budgets = [null].concat(bands.map(b => b.key));
  const combos = []; tiles.forEach((a, i) => { combos.push([a]); tiles.slice(i + 1).forEach(b => combos.push([a, b])); });
  let n = 0, differs = 0;
  for (const t of combos) for (const o of occs) for (const s of strengths) for (const w of whos) for (const bud of budgets) {
    const a = ans({ who: w, tiles: t, occ: o, strength: s, budget: bud });
    const res = Q.match(m, a, R.rank, { bands }); n++;
    const band = bands.find(b => b.key === bud);
    assert.ok(res.picks.length <= 3 && new Set(res.picks.map(p => p.id)).size === res.picks.length);
    const per = {};
    res.picks.forEach(p => {
      assert.ok(p.item.i && p.item.c === 'r', 'in stock, regular');
      if (w === 'her') assert.strictEqual(p.item.g, 3);
      if (band) assert.ok(Q.price3(p.item) >= band.min && Q.price3(p.item) <= band.max, 'budget respected');
      if (!p.explore) assert.ok(p.taste >= Q.MIN_TASTE, 'taste floor');
      assert.strictEqual(p.label === 'Worth Exploring', !!p.explore, 'Worth Exploring ⇔ explore pick');
      if (/Eau de Toilette/.test(p.why)) assert.strictEqual(s, 'subtle', 'EDT named only for Subtle');
      if (/Extrait|Elixir|Intense|· Parfum/.test(p.why)) assert.strictEqual(s, 'strong', 'strong concentrations named only for Strong');
      if (/Eau de Parfum(?! Intense)/.test(p.why)) assert.strictEqual(s, 'balanced', 'EDP named only for Balanced');
      if (/(^| )Floral( |$)/.test(p.why)) assert.ok(floralOK(p.item), 'Floral named only with a floral family or accord: ' + p.id);
      if (/^Musky/.test(p.why)) assert.ok(muskOK(p.item), 'Musky named only with a musk family or accord: ' + p.id);
      per[p.item.b] = (per[p.item.b] || 0) + 1;
    });
    Object.values(per).forEach(c => assert.ok(c <= Q.BRAND_CAP, 'brand cap'));
    res.picks.forEach((p, i) => res.picks.slice(i + 1).forEach(q => assert.ok(!Q.sameLine(p.item, q.item), 'one per fragrance line: ' + p.id + ' / ' + q.id)));
    if (n % 7 === 0) {               // sample: the pool vs a full-catalogue re-rank with the same rules
      const ex = Q.excluded(m, a, bands), vec = Q.buildAnchor(m, t);
      const all = R.rank(m, [], { anchor: { vec }, exclude: ex, collection: 'r', limit: 500, pool: 500, brandCap: 99, minCos: Q.MIN_COS, shuffle: false });
      const full = [], perB = new Map(), ranked = Q.rerank(all, a, m, vec).filter(r => r.taste >= Q.MIN_TASTE);
      for (const r of ranked) {
        if ((perB.get(r.item.b) || 0) >= Q.BRAND_CAP) continue;
        if (full.some(x => Q.sameLine(x.item, r.item))) continue;
        full.push(r); perB.set(r.item.b, (perB.get(r.item.b) || 0) + 1); if (full.length === 3) break;
      }
      // same "Woody & Oud" rule: a close-enough oud takes the last slot when none is shown
      const hasOud = r => Q.isOud(r.item, m);
      if (t.includes('woody') && full.length === 3 && !full.some(hasOud)) {
        const keep = full.slice(0, 2), kb = keep.map(r => r.item.b);
        const o = ranked.find(r => hasOud(r) && Q.coverage(r.item, t, m) === 1 && !keep.includes(r) && !keep.some(x => Q.sameLine(x.item, r.item)) && kb.filter(b => b === r.item.b).length < Q.BRAND_CAP);
        if (o && o.score >= Q.OUD_GAP * full[2].score) full.splice(2, 1, o);
      }
      const fullIds = full.map(r => r.id);
      if (fullIds.some(id => !res.picks.some(p => p.id === id))) differs++;
    }
  }
  const sampled = Math.floor(n / 7);
  assert.ok(differs / sampled <= 0.02, `taste pool agrees with a full re-rank (${differs}/${sampled} differ)`);
  // Explore with cards stays outside the chosen scent on real data
  const ex = Q.match(m, ans({ tiles: ['aquatic', Q.EXPLORE], occ: ['casual'] }), R.rank).picks.find(p => p.explore);
  if (ex) assert.ok(!/Aquatic/.test(ex.why), 'real explore pick is not another aquatic');
  console.log(`test-quiz: real-catalogue checks passed (${n} answer sets, pool agreement ${sampled - differs}/${sampled})`);
}
